package dev.raf.radar;
import org.junit.Test;import org.junit.Rule;import org.junit.rules.TemporaryFolder;import static org.junit.Assert.*;import java.io.*;import java.util.concurrent.atomic.AtomicLong;import org.json.*;
public class DiagnosticJournalTest {
 @Rule public TemporaryFolder temp=new TemporaryFolder();
 @Test public void rotatesHourAndPersistsOfflineQueueWithoutSecrets()throws Exception{AtomicLong now=new AtomicLong(100000000);File dir=temp.newFolder();DiagnosticJournal j=new DiagnosticJournal(dir,now::get);Throwable error=new IOException("password secret 55.01,61.02");j.event("taxi","timeout","error",error,429,15,900,"own");File queued=j.report("timeout",new JSONObject(),new JSONObject(),false);assertNotNull(queued);String payload=DiagnosticJournal.read(queued);assertFalse(payload.contains("secret"));assertFalse(payload.contains("55.01"));assertTrue(payload.contains("IOException"));DiagnosticJournal reopened=new DiagnosticJournal(dir,now::get);assertNotNull(reopened.pending());now.addAndGet(DiagnosticJournal.RETENTION+1);reopened.maintain();assertEquals(0,reopened.events.length());assertNotNull(reopened.pending());reopened.acknowledged(reopened.pending());assertNull(reopened.pending());}
 @Test public void reportCooldownRetainsNewErrorsAndQueueIsBounded()throws Exception{AtomicLong now=new AtomicLong(System.currentTimeMillis());DiagnosticJournal j=new DiagnosticJournal(temp.newFolder(),now::get);for(int i=0;i<12;i++){j.event("taxi","failed","error",null,500,-1,-1,null);assertNotNull(j.report("failed",new JSONObject(),new JSONObject(),true));now.incrementAndGet();}assertEquals(8,j.root.listFiles((d,n)->n.startsWith("report-")).length);j.event("gps","missing","error",null,0,-1,-1,null);assertNull(j.report("missing",new JSONObject(),new JSONObject(),false));DiagnosticJournal reopened=new DiagnosticJournal(j.root,now::get);assertTrue(reopened.dirty);now.addAndGet(DiagnosticJournal.REPORT_GAP);assertNotNull(reopened.report("window",new JSONObject(),new JSONObject(),false));}
 @Test public void verboseDaySurvivesRestartAndManualExportIsComplete()throws Exception{AtomicLong now=new AtomicLong(100000000);DiagnosticJournal j=new DiagnosticJournal(temp.newFolder(),now::get);for(int i=0;i<1600;i++){j.event("network","request","info",null,200,12,-1,null,new JSONObject().put("requestId",i).put("rttMs",12).put("password","secret").put("lat",55));now.incrementAndGet();}j.maintain();DiagnosticJournal reopened=new DiagnosticJournal(j.root,now::get);assertEquals(1600,reopened.events.length());File report=reopened.report("manual_report",new JSONObject(),new JSONObject(),true);JSONObject payload=new JSONObject(DiagnosticJournal.read(report));assertEquals(1600,payload.getJSONArray("events").length());assertFalse(payload.toString().contains("secret"));assertFalse(payload.toString().contains("lat"));now.addAndGet(2*DiagnosticJournal.HOUR);reopened.maintain();assertEquals(1600,reopened.events.length());}
}
